{
  "commitMessage": "feat(invoices): add overdue status support and styling in StatusBadge",
  "files": [
    {
      "path": "src/lib/status.ts",
      "content": "import type { InvoiceStatus, QuoteStatus } from "@/db/schema";
import { todayIso } from "@/lib/dates";

export type InvoiceDisplayStatus = InvoiceStatus | "overdue";

export const quoteStatusLabels: Record<QuoteStatus, string> = {
  draft: "Borrador",
  sent: "Enviado",
  accepted: "Aceptado",
  rejected: "Rechazado",
};

export const invoiceStatusLabels: Record<InvoiceDisplayStatus, string> = {
  pending: "Pendiente",
  paid: "Pagada",
  overdue: "Vencida",
};

export function getInvoiceDisplayStatus(
  status: InvoiceStatus,
  dueAt: string,
  nowIso: string = todayIso()
): InvoiceDisplayStatus {
  if (status === "pending" && dueAt < nowIso) {
    return "overdue";
  }
  return status;
}
"
