    {
      "path": "src/components/status-badge.tsx",
      "content": "import type { InvoiceStatus, QuoteStatus } from "@/db/schema";
import {
  getInvoiceDisplayStatus,
  invoiceStatusLabels,
  quoteStatusLabels,
  type InvoiceDisplayStatus,
} from "@/lib/status";

const colors: Record<QuoteStatus | InvoiceDisplayStatus, string> = {
  draft: "bg-slate-100 text-slate-700",
  sent: "bg-blue-100 text-blue-800",
  accepted: "bg-green-100 text-green-800",
  rejected: "bg-red-100 text-red-800",
  pending: "bg-amber-100 text-amber-800",
  paid: "bg-green-100 text-green-800",
  overdue: "bg-red-100 text-red-800",
};

type Props =
  | { kind: "quote"; status: QuoteStatus }
  | {
      kind: "invoice";
      status: InvoiceStatus | InvoiceDisplayStatus;
      dueAt?: string;
    };

export function StatusBadge(props: Props) {
  if (props.kind === "quote") {
    const label = quoteStatusLabels[props.status];
    return (
      <span
        data-testid="status-badge"
        data-status={props.status}
        className={`inline-flex rounded-full px-2 py-0.5 text-xs font-medium whitespace-nowrap ${colors[props.status]}`}
      >
        {label}
      </span>
    );
  }

  const resolvedStatus: InvoiceDisplayStatus =
    props.status === "overdue"
      ? "overdue"
      : props.dueAt
        ? getInvoiceDisplayStatus(props.status as InvoiceStatus, props.dueAt)
        : (props.status as InvoiceDisplayStatus);

  const label = invoiceStatusLabels[resolvedStatus];
  return (
    <span
      data-testid="status-badge"
      data-status={resolvedStatus}
      className={`inline-flex rounded-full px-2 py-0.5 text-xs font-medium whitespace-nowrap ${colors[resolvedStatus]}`}
    >
      {label}
    </span>
  );
}
"
    }
  ],
  "notes": "Se ha añadido el tipo `InvoiceDisplayStatus` ('pending' | 'paid' | 'overdue') y la función `getInvoiceDisplayStatus` en `src/lib/status.ts` para determinar si una factura pendiente tiene la fecha de vencimiento superada. Además, se ha actualizado `StatusBadge` para dar soporte al estado 'overdue' con la etiqueta 'Vencida', `data-status="overdue"` y estilos en rojo (`bg-red-100 text-red-800`), aceptando opcionalmente `dueAt` o directamente el estado.",
  "evidence": [
